import java.io.*;
import java.util.*;
import java.text.DecimalFormat;

public class Main {
    public static void main(String[] args) throws Exception {
        String filePath = "<tmp>";

        BufferedReader br = new BufferedReader(new FileReader(filePath));
        String line = br.readLine(); // skip header

        Map<String, List<Double>> deptSalaries = new TreeMap<>();
        Map<String, Integer> deptCounts = new TreeMap<>();
        String highestName = "";
        double highestSalary = -1;
        double totalBudget = 0;

        while ((line = br.readLine()) != null) {
            if (line.trim().isEmpty()) continue;
            String[] parts = line.split(",");
            String name = parts[1].trim();
            String department = parts[2].trim();
            double salary = Double.parseDouble(parts[3].trim());

            deptSalaries.computeIfAbsent(department, k -> new ArrayList<>()).add(salary);
            deptCounts.put(department, deptCounts.getOrDefault(department, 0) + 1);

            if (salary > highestSalary) {
                highestSalary = salary;
                highestName = name;
            }

            totalBudget += salary;
        }
        br.close();

        DecimalFormat avgFmt = new DecimalFormat("#,##0.00");
        DecimalFormat intFmt = new DecimalFormat("#,##0");

        System.out.println("=== Salary Report ===");
        System.out.println();
        System.out.println("Average Salary by Department:");
        for (Map.Entry<String, List<Double>> entry : deptSalaries.entrySet()) {
            double avg = entry.getValue().stream().mapToDouble(Double::doubleValue).average().orElse(0);
            System.out.printf("  %s: $%s%n", entry.getKey(), avgFmt.format(avg));
        }
        System.out.println();
        System.out.printf("Highest Paid: %s ($%s)%n", highestName, intFmt.format((long) Math.round(highestSalary)));
        System.out.println();
        System.out.println("Departments with >2 employees:");
        for (Map.Entry<String, Integer> entry : deptCounts.entrySet()) {
            if (entry.getValue() > 2) {
                System.out.printf("  %s (%d employees)%n", entry.getKey(), entry.getValue());
            }
        }
        System.out.println();
        System.out.printf("Total Budget: $%s%n", intFmt.format((long) Math.round(totalBudget)));
    }
}

