import Foundation

let filePath = "<tmp>"

guard let content = try? String(contentsOfFile: filePath, encoding: .utf8) else {
    FileHandle.standardError.write("Error reading file\n".data(using: .utf8)!)
    exit(1)
}

let lines = content.components(separatedBy: "\n").filter { !$0.trimmingCharacters(in: .whitespaces).isEmpty }

let pattern = "^\\[(\\d{4}-\\d{2}-\\d{2}) (\\d{2}):(\\d{2}):(\\d{2})\\] (\\S+) \\(([^)]+)\\) - (.+)$"
let regex = try! NSRegularExpression(pattern: pattern)

var levelCounts: [String: Int] = [:]
var errorComponentCounts: [String: Int] = [:]
var errorMessages: Set<String> = []
var hourCounts: [Int: Int] = [:]

for line in lines {
    let nsLine = line as NSString
    let range = NSRange(location: 0, length: nsLine.length)
    if let match = regex.firstMatch(in: line, options: [], range: range) {
        let hour = Int((nsLine.substring(with: match.range(at: 2))))!
        let level = nsLine.substring(with: match.range(at: 5))
        let component = nsLine.substring(with: match.range(at: 6))
        let message = nsLine.substring(with: match.range(at: 7))

        levelCounts[level, default: 0] += 1
        hourCounts[hour, default: 0] += 1

        if level == "ERROR" {
            errorComponentCounts[component, default: 0] += 1
            errorMessages.insert(message)
        }
    }
}

print("=== Log Analysis ===")
print("")
print("Entries by Level:")
for level in levelCounts.keys.sorted() {
    print("  \(level): \(levelCounts[level]!)")
}
print("")
if let (comp, count) = errorComponentCounts.max(by: { $0.value < $1.value }) {
    print("Component with Most Errors: \(comp) (\(count) errors)")
} else {
    print("Component with Most Errors: N/A (0 errors)")
}
print("")
print("Unique Error Messages:")
for msg in errorMessages.sorted() {
    print("  - \(msg)")
}
print("")
if let (hour, count) = hourCounts.max(by: { $0.value < $1.value }) {
    let hh = String(format: "%02d", hour)
    print("Busiest Hour: \(hh):00 (\(count) entries)")
} else {
    print("Busiest Hour: 00:00 (0 entries)")
}

