    let fields = lines[i].components(separatedBy: ",")
    guard fields.count >= 4 else { continue }
    let name = fields[1].trimmingCharacters(in: .whitespaces)
    let dept = fields[2].trimmingCharacters(in: .whitespaces)
    let salaryStr = fields[3].trimmingCharacters(in: .whitespaces)
    guard let salary = Double(salaryStr) else { continue }
    employees.append(("", name, dept, salary))
