import java.io.*;
import java.util.*;
import java.util.regex.*;

public class Main {
    public static void main(String[] args) throws Exception {
        String filePath = "<tmp>";

        List<String> lines = new ArrayList<>();
        try (BufferedReader br = new BufferedReader(new FileReader(filePath))) {
            String line;
            while ((line = br.readLine()) != null) {
                if (!line.trim().isEmpty()) {
                    lines.add(line);
                }
            }
        }

        Pattern pattern = Pattern.compile("\\[(\\d{4}-\\d{2}-\\d{2} (\\d{2}):(\\d{2}):(\\d{2}))\\] (\\S+) \\(([^)]+)\\) - (.+)");

        Map<String, Integer> levelCounts = new TreeMap<>();
        Map<String, Integer> errorComponentCounts = new HashMap<>();
        Set<String> errorMessages = new TreeSet<>();
        Map<String, Integer> hourCounts = new HashMap<>();

        for (String line : lines) {
            Matcher m = pattern.matcher(line.trim());
            if (m.matches()) {
                String hour = m.group(2);
                String level = m.group(5);
                String component = m.group(6);
                String message = m.group(7);

                levelCounts.merge(level, 1, Integer::sum);
                hourCounts.merge(hour, 1, Integer::sum);

                if (level.equalsIgnoreCase("ERROR")) {
                    errorComponentCounts.merge(component, 1, Integer::sum);
                    errorMessages.add(message);
                }
            }
        }

        String topComponent = "";
        int topCount = 0;
        for (Map.Entry<String, Integer> e : errorComponentCounts.entrySet()) {
            if (e.getValue() > topCount || (e.getValue() == topCount && e.getKey().compareTo(topComponent) < 0)) {
                topCount = e.getValue();
                topComponent = e.getKey();
            }
        }

        String busiestHour = "00";
        int busiestCount = 0;
        for (Map.Entry<String, Integer> e : hourCounts.entrySet()) {
            if (e.getValue() > busiestCount || (e.getValue() == busiestCount && e.getKey().compareTo(busiestHour) < 0)) {
                busiestCount = e.getValue();
                busiestHour = e.getKey();
            }
        }

        System.out.println("=== Log Analysis ===");
        System.out.println();
        System.out.println("Entries by Level:");
        for (Map.Entry<String, Integer> e : levelCounts.entrySet()) {
            System.out.println("  " + e.getKey() + ": " + e.getValue());
        }
        System.out.println();
        System.out.println("Component with Most Errors: " + topComponent + " (" + topCount + " errors)");
        System.out.println();
        System.out.println("Unique Error Messages:");
        for (String msg : errorMessages) {
            System.out.println("  - " + msg);
        }
        System.out.println();
        System.out.println("Busiest Hour: " + busiestHour + ":00 (" + busiestCount + " entries)");
    }
}

