use std::collections::BTreeMap;
use std::fs;

#[derive(Debug, Clone, PartialEq)]
enum Json {
    Null,
    Bool(bool),
    Int(i64),
    Float(f64),
    String(String),
    Array(Vec<Json>),
    Object(BTreeMap<String, Json>),
}

struct Parser {
    chars: Vec<char>,
    pos: usize,
}

impl Parser {
    fn new(s: &str) -> Self {
        Parser { chars: s.chars().collect(), pos: 0 }
    }

    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }

    fn next(&mut self) -> Option<char> {
        let c = self.peek();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }

    fn skip_whitespace(&mut self) {
        while let Some(c) = self.peek() {
            if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
                self.pos += 1;
            } else {
                break;
            }
        }
    }

    fn parse(&mut self) -> Json {
        self.skip_whitespace();
        let c = self.peek().unwrap();
        match c {
            '{' => self.parse_object(),
            '[' => self.parse_array(),
            '"' => Json::String(self.parse_string()),
            't' => {
                self.expect("true");
                Json::Bool(true)
            }
            'f' => {
                self.expect("false");
                Json::Bool(false)
            }
            'n' => {
                self.expect("null");
                Json::Null
            }
            _ => self.parse_number(),
        }
    }

    fn expect(&mut self, s: &str) {
        for c in s.chars() {
            let got = self.next().unwrap();
            assert_eq!(got, c, "expected '{}' got '{}'", c, got);
        }
    }

    fn parse_string(&mut self) -> String {
        self.next(); // consume opening "
        let mut result = String::new();
        loop {
            let c = self.next().unwrap();
            if c == '"' {
                break;
            }
            if c == '\\' {
                let esc = self.next().unwrap();
                match esc {
                    '"' => result.push('"'),
                    '\\' => result.push('\\'),
                    '/' => result.push('/'),
                    'b' => result.push('\u{0008}'),
                    'f' => result.push('\u{000C}'),
                    'n' => result.push('\n'),
                    'r' => result.push('\r'),
                    't' => result.push('\t'),
                    'u' => {
                        let mut code = 0u32;
                        for _ in 0..4 {
                            let h = self.next().unwrap();
                            let d = hex_val(h);
                            code = code * 16 + d;
                        }
                        if (0xD800..=0xDBFF).contains(&code) {
                            if self.peek() == Some('\\') {
                                let save = self.pos;
                                self.pos += 1;
                                if self.peek() == Some('u') {
                                    self.pos += 1;
                                    let mut low = 0u32;
                                    for _ in 0..4 {
                                        let h = self.next().unwrap();
                                        let d = hex_val(h);
                                        low = low * 16 + d;
                                    }
                                    if (0xDC00..=0xDFFF).contains(&low) {
                                        let cp = 0x10000 + ((code - 0xD800) << 10) + (low - 0xDC00);
                                        result.push(char::from_u32(cp).unwrap_or('\u{FFFD}'));
                                        continue;
                                    }
                                }
                                self.pos = save;
                            }
                        }
                        result.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                    }
                    _ => unreachable!(),
                }
            } else {
                result.push(c);
            }
        }
        result
    }

    fn parse_number(&mut self) -> Json {
        let start = self.pos;
        let mut is_float = false;
        while let Some(c) = self.peek() {
            if c == '-' || c.is_ascii_digit() {
                self.pos += 1;
            } else if c == '.' || c == 'e' || c == 'E' {
                is_float = true;
                self.pos += 1;
            } else {
                break;
            }
        }
        let s: String = self.chars[start..self.pos].iter().collect();
        if is_float {
            Json::Float(s.parse::<f64>().unwrap())
        } else {
            Json::Int(s.parse::<i64>().unwrap())
        }
    }

    fn parse_object(&mut self) -> Json {
        self.next(); // {
        let mut map = BTreeMap::new();
        self.skip_whitespace();
        if self.peek() == Some('}') {
            self.next();
            return Json::Object(map);
        }
        loop {
            self.skip_whitespace();
            let key = self.parse_string();
            self.skip_whitespace();
            self.next(); // :
            self.skip_whitespace();
            let val = self.parse();
            map.insert(key, val);
            self.skip_whitespace();
            match self.next() {
                Some(',') => continue,
                Some('}') => break,
                _ => unreachable!(),
            }
        }
        Json::Object(map)
    }

    fn parse_array(&mut self) -> Json {
        self.next(); // [
        let mut arr = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some(']') {
            self.next();
            return Json::Array(arr);
        }
        loop {
            self.skip_whitespace();
            let val = self.parse();
            arr.push(val);
            self.skip_whitespace();
            match self.next() {
                Some(',') => continue,
                Some(']') => break,
                _ => unreachable!(),
            }
        }
        Json::Array(arr)
    }
}

fn hex_val(c: char) -> u32 {
    match c {
        '0'..='9' => (c as u32) - ('0' as u32),
        'a'..='f' => (c as u32) - ('a' as u32) + 10,
        'A'..='F' => (c as u32) - ('A' as u32) + 10,
        _ => 0,
    }
}

fn escape_string(s: &str) -> String {
    let mut result = String::new();
    for c in s.chars() {
        match c {
            '"' => result.push_str("\\\""),
            '\\' => result.push_str("\\\\"),
            '\n' => result.push_str("\\n"),
            '\r' => result.push_str("\\r"),
            '\t' => result.push_str("\\t"),
            '\u{0008}' => result.push_str("\\b"),
            '\u{000C}' => result.push_str("\\f"),
            c if (c as u32) < 0x20 => {
                result.push_str(&format!("\\u{:04x}", c as u32));
            }
            c => result.push(c),
        }
    }
    result
}

fn format_float(f: f64) -> String {
    if f.is_nan() || f.is_infinite() {
        return "null".to_string();
    }
    let s = format!("{:?}", f);
    s
}

fn serialize_json(val: &Json, indent: usize) -> String {
    let pad = "  ".repeat(indent);
    let pad_inner = "  ".repeat(indent + 1);
    match val {
        Json::Null => "null".to_string(),
        Json::Bool(b) => b.to_string(),
        Json::Int(n) => n.to_string(),
        Json::Float(f) => format_float(*f),
        Json::String(s) => format!("\"{}\"", escape_string(s)),
        Json::Array(arr) => {
            if arr.is_empty() {
                return "[]".to_string();
            }
            let items: Vec<String> = arr
                .iter()
                .map(|item| format!("{}{}", pad_inner, serialize_json(item, indent + 1)))
                .collect();
            format!("[\n{}\n{}]", items.join(",\n"), pad)
        }
        Json::Object(map) => {
            if map.is_empty() {
                return "{}".to_string();
            }
            let items: Vec<String> = map
                .iter()
                .map(|(k, v)| {
                    format!(
                        "{}\"{}\": {}",
                        pad_inner,
                        escape_string(k),
                        serialize_json(v, indent + 1)
                    )
                })
                .collect();
            format!("{{\n{}\n{}}}", items.join(",\n"), pad)
        }
    }
}

fn deep_merge(a: &Json, b: &Json) -> Json {
    match (a, b) {
        (Json::Object(map_a), Json::Object(map_b)) => {
            let mut result = map_a.clone();
            for (key, val_b) in map_b {
