        let line = line.trim();
        if line.is_empty() {
            continue;
        }

        // Parse: [YYYY-MM-DD HH:MM:SS] LEVEL (component) - message
        let bracket_start = line.find('['].unwrap();
        let bracket_end = line.find(']').unwrap();
        let timestamp = &line[bracket_start + 1..bracket_end];

        // Extract hour (positions 11-12 in "YYYY-MM-DD HH:MM:SS")
        let hour = &timestamp[11..13];

        // After "]", we have " LEVEL (component) - message"
        let rest = &line[bracket_end + 1..];

        // Parse LEVEL
        let space_idx = rest.find(' ').unwrap();
        let level = &rest[..space_idx];

        // After level, we have " (component) - message"
        let after_level = &rest[space_idx + 1..];

        // Parse component
        let comp_start = after_level.find('(').unwrap();
        let comp_end = after_level.find(')').unwrap();
        let component = &after_level[comp_start + 1..comp_end];

        // After component, we have " - message"
        let after_comp = &after_level[comp_end + 1..];
        let message = after_comp.trim_start_matches(" - ").to_string();

        // Count by level
        *level_counts.entry(level.to_string()).or_insert(0) += 1;

        // Count errors by component
        if level == "ERROR" {
            *error_component_counts.entry(component.to_string()).or_insert(0) += 1;
            error_messages.push(message);
        }

        // Count by hour
        *hour_counts.entry(hour.to_string()).or_insert(0) += 1;
    }

