    unique_msgs.dedup();
    for msg in &unique_msgs {
        println!("  - {}", msg);
    }
    println!();

    // Busiest Hour (alphabetically first on tie)
    let mut busiest: Option<(&String, usize)> = None;
    for (hour, count) in &hour_counts {
        match busiest {
            None => busiest = Some((hour, *count)),
