} DeptInfo;

static int compare_depts(const void *a, const void *b) {
    const DeptInfo *da = (const DeptInfo *)a;
    const DeptInfo *db = (const DeptInfo *)b;
    return strcmp(da->dept, db->dept);
}

static void format_money_comma(double val, int decimals, char *buf, size_t bufsize) {
    char numbuf[64];
    if (decimals == 2) {
        snprintf(numbuf, sizeof(numbuf), "%.2f", val);
    } else {
        long long ival;
        if (val >= 0)
            ival = (long long)(val + 0.5);
        else
            ival = (long long)(val - 0.5);
        snprintf(numbuf, sizeof(numbuf), "%lld", ival);
    }

    int len = (int)strlen(numbuf);
    int dot_pos = -1;
    for (int i = 0; i < len; i++) {
        if (numbuf[i] == '.') {
            dot_pos = i;
            break;
        }
    }
    int int_len = (dot_pos >= 0) ? dot_pos : len;

    int pos = 0;
    for (int i = 0; i < int_len; i++) {
        int from_right = int_len - 1 - i;
        if (from_right > 0 && from_right % 3 == 0) {
            if (pos + 1 < (int)bufsize)
                buf[pos++] = ',';
        }
        if (pos + 1 < (int)bufsize)
            buf[pos++] = numbuf[i];
    }
    if (dot_pos >= 0) {
        for (int i = dot_pos; i < len; i++) {
            if (pos + 1 < (int)bufsize)
                buf[pos++] = numbuf[i];
        }
    }
    buf[pos] = '\0';
}

int main(void) {
    const char *filepath = "<tmp>";

    FILE *f = fopen(filepath, "r");
    if (!f) {
        fprintf(stderr, "Error: cannot open file\n");
        return 1;
    }

    int capacity = 256;
    Employee *employees = (Employee *)malloc((size_t)capacity * sizeof(Employee));
    DeptInfo *depts = (DeptInfo *)malloc((size_t)capacity * sizeof(DeptInfo));
    if (!employees || !depts) {
        fclose(f);
        return 1;
    }

    int n_employees = 0;
    int n_depts = 0;

    char *line = (char *)malloc(MAX_LINE);
    if (!line) {
        fclose(f);
        free(employees);
        free(depts);
        return 1;
    }

    int first_line = 1;

    while (fgets(line, MAX_LINE, f)) {
        line[strcspn(line, "\r\n")] = '\0';
