        employees[n_employees].name[MAX_NAME - 1] = '\0';
        employees[n_employees].salary = atof(fields[3]);

        int found = -1;
        for (int i = 0; i < n_depts; i++) {
            if (strcmp(depts[i].dept, fields[2]) == 0) {
                found = i;
                break;
            }
        }
        if (found == -1) {
            if (n_depts >= capacity) {
                capacity *= 2;
                depts = (DeptInfo *)realloc(depts, (size_t)capacity * sizeof(DeptInfo));
                employees = (Employee *)realloc(employees, (size_t)capacity * sizeof(Employee));
                if (!depts || !employees) {
                    fclose(f);
                    free(line);
                    return 1;
                }
            }
            strncpy(depts[n_depts].dept, fields[2], MAX_DEPT - 1);
            depts[n_depts].dept[MAX_DEPT - 1] = '\0';
            depts[n_depts].total_salary = 0.0;
            depts[n_depts].count = 0;
            found = n_depts;
            n_depts++;
        }
        depts[found].total_salary += employees[n_employees].salary;
        depts[found].count++;

        n_employees++;
    }

    free(line);
    fclose(f);

    if (n_employees == 0) {
        free(employees);
        free(depts);
        return 0;
    }

    qsort(depts, (size_t)n_depts, sizeof(DeptInfo), compare_depts);

    int highest_idx = 0;
    for (int i = 1; i < n_employees; i++) {
        if (employees[i].salary > employees[highest_idx].salary) {
            highest_idx = i;
        }
    }

    double total_budget = 0.0;
    for (int i = 0; i < n_employees; i++) {
        total_budget += employees[i].salary;
    }

    char moneybuf[128];

    printf("=== Salary Report ===\n");
    printf("\n");
    printf("Average Salary by Department:\n");
    for (int i = 0; i < n_depts; i++) {
        double avg = depts[i].total_salary / (double)depts[i].count;
        format_money_comma(avg, 2, moneybuf, sizeof(moneybuf));
        printf("  %s: $%s\n", depts[i].dept, moneybuf);
    }

    printf("\n");
    format_money_comma(employees[highest_idx].salary, 0, moneybuf, sizeof(moneybuf));
    printf("Highest Paid: %s ($%s)\n", employees[highest_idx].name, moneybuf);

    printf("\n");
    printf("Departments with >2 employees:\n");
    for (int i = 0; i < n_depts; i++) {
        if (depts[i].count > 2) {
            printf("  %s (%d employees)\n", depts[i].dept, depts[i].count);
        }
    }

    printf("\n");
    format_money_comma(total_budget, 0, moneybuf, sizeof(moneybuf));
    printf("Total Budget: $%s\n", moneybuf);

    free(employees);
    free(depts);
    return 0;
}

