    fseek(f, 0, SEEK_END);
    long len = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = malloc((size_t)len + 1);
    if (!buf) { fclose(f); return NULL; }
    size_t rd = fread(buf, 1, (size_t)len, f);
    buf[rd] = '\0';
    fclose(f);
    *out_len = (long)rd;
    return buf;
}

static void skip_ws(const char **p) {
    while (**p == ' ' || **p == '\t' || **p == '\n' || **p == '\r') (*p)++;
}

static char *parse_string(const char **p) {
    skip_ws(p);
    if (**p != '"') return NULL;
    (*p)++;
    char *start = (char *)*p;
    while (**p && **p != '"') {
        if (**p == '\\') (*p)++;
        (*p)++;
    }
    long len = (long)((char *)*p - start);
    char *s = malloc((size_t)len + 1);
    memcpy(s, start, (size_t)len);
    s[len] = '\0';
    if (**p == '"') (*p)++;
    return s;
}

static long parse_number(const char **p) {
    skip_ws(p);
    long val = 0;
    int neg = 0;
    if (**p == '-') { neg = 1; (*p)++; }
    while (**p >= '0' && **p <= '9') {
        val = val * 10 + (**p - '0');
        (*p)++;
    }
    return neg ? -val : val;
}

