    const char *s;
    int pos;
    int len;
} parser;

static void p_skip_ws(parser *p) {
    while (p->pos < p->len) {
        char c = p->s[p->pos];
        if (c == ' ' || c == '\t' || c == '\n' || c == '\r') p->pos++;
        else break;
    }
}

static json_value *p_parse_value(parser *p);

static char *p_parse_string_raw(parser *p) {
    if (p->pos >= p->len || p->s[p->pos] != '"') return NULL;
    p->pos++;
    int cap = 64, cnt = 0;
    char *buf = (char *)malloc(cap);
    if (!buf) { fprintf(stderr, "OOM\n"); exit(1); }
    while (p->pos < p->len && p->s[p->pos] != '"') {
        char c = p->s[p->pos];
        if (c == '\\') {
            p->pos++;
            if (p->pos >= p->len) break;
            char e = p->s[p->pos];
            if (e == '"') { if (cnt+1>=cap){cap*=2;buf=realloc(buf,cap);} buf[cnt++]='"'; p->pos++; }
            else if (e == '\\') { if (cnt+1>=cap){cap*=2;buf=realloc(buf,cap);} buf[cnt++]='\\'; p->pos++; }
            else if (e == '/') { if (cnt+1>=cap){cap*=2;buf=realloc(buf,cap);} buf[cnt++]='/'; p->pos++; }
            else if (e == 'b') { if (cnt+1>=cap){cap*=2;buf=realloc(buf,cap);} buf[cnt++]='\b'; p->pos++; }
            else if (e == 'f') { if (cnt+1>=cap){cap*=2;buf=realloc(buf,cap);} buf[cnt++]='\f'; p->pos++; }
            else if (e == 'n') { if (cnt+1>=cap){cap*=2;buf=realloc(buf,cap);} buf[cnt++]='\n'; p->pos++; }
            else if (e == 'r') { if (cnt+1>=cap){cap*=2;buf=realloc(buf,cap);} buf[cnt++]='\r'; p->pos++; }
            else if (e == 't') { if (cnt+1>=cap){cap*=2;buf=realloc(buf,cap);} buf[cnt++]='\t'; p->pos++; }
            else if (e == 'u') {
                p->pos++;
                if (p->pos + 4 > p->len) break;
                unsigned int code = 0;
                for (int i = 0; i < 4; i++) {
                    char hc = p->s[p->pos++];
                    code <<= 4;
                    if (hc >= '0' && hc <= '9') code |= (hc - '0');
                    else if (hc >= 'a' && hc <= 'f') code |= (hc - 'a' + 10);
                    else if (hc >= 'A' && hc <= 'F') code |= (hc - 'A' + 10);
                    else { free(buf); return NULL; }
                }
                if (code >= 0xD800 && code <= 0xDBFF && p->pos + 5 < p->len && p->s[p->pos] == '\\' && p->s[p->pos+1] == 'u') {
                    p->pos += 2;
                    unsigned int lo = 0;
                    for (int i = 0; i < 4; i++) {
                        char hc = p->s[p->pos++];
                        lo <<= 4;
                        if (hc >= '0' && hc <= '9') lo |= (hc - '0');
                        else if (hc >= 'a' && hc <= 'f') lo |= (hc - 'a' + 10);
                        else if (hc >= 'A' && hc <= 'F') lo |= (hc - 'A' + 10);
                        else { free(buf); return NULL; }
                    }
                    if (lo >= 0xDC00 && lo <= 0xDFFF) {
                        code = 0x10000 + ((code - 0xD800) << 10) + (lo - 0xDC00);
                    }
                }
                int need;
                if (code < 0x80) need = 1;
                else if (code < 0x800) need = 2;
                else if (code < 0x10000) need = 3;
                else need = 4;
                if (cnt + need >= cap) { cap *= 2; while (cnt + need >= cap) cap *= 2; buf = realloc(buf, cap); }
                if (code < 0x80) {
                    buf[cnt++] = (char)code;
                } else if (code < 0x800) {
                    buf[cnt++] = (char)(0xC0 | (code >> 6));
                    buf[cnt++] = (char)(0x80 | (code & 0x3F));
                } else if (code < 0x10000) {
                    buf[cnt++] = (char)(0xE0 | (code >> 12));
                    buf[cnt++] = (char)(0x80 | ((code >> 6) & 0x3F));
                    buf[cnt++] = (char)(0x80 | (code & 0x3F));
                } else {
                    buf[cnt++] = (char)(0xF0 | (code >> 18));
                    buf[cnt++] = (char)(0x80 | ((code >> 12) & 0x3F));
                    buf[cnt++] = (char)(0x80 | ((code >> 6) & 0x3F));
                    buf[cnt++] = (char)(0x80 | (code & 0x3F));
                }
            } else {
                p->pos++;
            }
        } else {
            if (cnt + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); if (!buf) { fprintf(stderr, "OOM\n"); exit(1); } }
            buf[cnt++] = c;
            p->pos++;
        }
    }
    if (p->pos < p->len && p->s[p->pos] == '"') p->pos++;
    if (cnt >= cap) { cap++; buf = realloc(buf, cap); }
    buf[cnt] = '\0';
    return buf;
}

static json_value *p_parse_string(parser *p) {
    char *s = p_parse_string_raw(p);
    if (!s) return NULL;
    json_value *v = json_new(JSON_STRING);
    v->str_val = s;
    return v;
}

static json_value *p_parse_number(parser *p) {
    int start = p->pos;
    if (p->pos < p->len && (p->s[p->pos] == '-' || p->s[p->pos] == '+')) p->pos++;
    while (p->pos < p->len && isdigit((unsigned char)p->s[p->pos])) p->pos++;
    if (p->pos < p->len && p->s[p->pos] == '.') {
        p->pos++;
        while (p->pos < p->len && isdigit((unsigned char)p->s[p->pos])) p->pos++;
    }
    if (p->pos < p->len && (p->s[p->pos] == 'e' || p->s[p->pos] == 'E')) {
        p->pos++;
        if (p->pos < p->len && (p->s[p->pos] == '-' || p->s[p->pos] == '+')) p->pos++;
        while (p->pos < p->len && isdigit((unsigned char)p->s[p->pos])) p->pos++;
    }
    int len = p->pos - start;
    char *tmp = (char *)malloc(len + 1);
    memcpy(tmp, p->s + start, len);
    tmp[len] = '\0';
    double val = strtod(tmp, NULL);
    free(tmp);
    json_value *v = json_new(JSON_NUMBER);
    v->num_val = val;
    return v;
}

static json_value *p_parse_array(parser *p) {
    p->pos++;
    json_value *v = json_new(JSON_ARRAY);
    p_skip_ws(p);
    if (p->pos < p->len && p->s[p->pos] == ']') { p->pos++; return v; }
    while (1) {
        p_skip_ws(p);
        json_value *item = p_parse_value(p);
        if (!item) break;
        json_arr_push(v, item);
        p_skip_ws(p);
        if (p->pos < p->len && p->s[p->pos] == ',') { p->pos++; continue; }
        if (p->pos < p->len && p->s[p->pos] == ']') { p->pos++; break; }
        break;
    }
    return v;
}

static json_value *p_parse_object(parser *p) {
    p->pos++;
    json_value *v = json_new(JSON_OBJECT);
    p_skip_ws(p);
    if (p->pos < p->len && p->s[p->pos] == '}') { p->pos++; return v; }
    while (1) {
        p_skip_ws(p);
        char *key = p_parse_string_raw(p);
        if (!key) break;
        p_skip_ws(p);
        if (p->pos >= p->len || p->s[p->pos] != ':') { free(key); break; }
        p->pos++;
        p_skip_ws(p);
        json_value *val = p_parse_value(p);
        if (!val) { free(key); break; }
        json_obj_put(v, key, val);
        free(key);
        p_skip_ws(p);
        if (p->pos < p->len && p->s[p->pos] == ',') { p->pos++; continue; }
        if (p->pos < p->len && p->s[p->pos] == '}') { p->pos++; break; }
        break;
    }
    return v;
}

static json_value *p_parse_value(parser *p) {
    p_skip_ws(p);
    if (p->pos >= p->len) return NULL;
    char c = p->s[p->pos];
    if (c == '{') return p_parse_object(p);
    if (c == '[') return p_parse_array(p);
    if (c == '"') return p_parse_string(p);
    if (c == 't' && p->pos + 4 <= p->len && strncmp(p->s + p->pos, "true", 4) == 0) {
        p->pos += 4;
        json_value *v = json_new(JSON_BOOL);
        v->bool_val = 1;
        return v;
    }
    if (c == 'f' && p->pos + 5 <= p->len && strncmp(p->s + p->pos, "false", 5) == 0) {
        p->pos += 5;
        json_value *v = json_new(JSON_BOOL);
        v->bool_val = 0;
        return v;
    }
    if (c == 'n' && p->pos + 4 <= p->len && strncmp(p->s + p->pos, "null", 4) == 0) {
        p->pos += 4;
        return json_new(JSON_NULL);
    }
    if (c == '-' || (c >= '0' && c <= '9')) return p_parse_number(p);
    return NULL;
}

static json_value *parse_json(const char *text, int len) {
    parser p = { text, 0, len };
    json_value *v = p_parse_value(&p);
    return v;
}

/* Deep equality for dedup */
static int json_equal(const json_value *a, const json_value *b) {
    if (a->type != b->type) return 0;
    switch (a->type) {
        case JSON_NULL: return 1;
        case JSON_BOOL: return a->bool_val == b->bool_val;
        case JSON_NUMBER: return a->num_val == b->num_val;
        case JSON_STRING: return a->str_val && b->str_val && strcmp(a->str_val, b->str_val) == 0;
        case JSON_ARRAY:
            if (a->arr_count != b->arr_count) return 0;
            for (int i = 0; i < a->arr_count; i++)
                if (!json_equal(a->arr_items[i], b->arr_items[i])) return 0;
            return 1;
        case JSON_OBJECT:
            if (a->obj_count != b->obj_count) return 0;
            for (int i = 0; i < a->obj_count; i++) {
                int found = 0;
                for (int j = 0; j < b->obj_count; j++) {
                    if (a->obj_keys[i] && b->obj_keys[j] && strcmp(a->obj_keys[i], b->obj_keys[j]) == 0) {
                        if (!json_equal(a->obj_vals[i], b->obj_vals[j])) return 0;
                        found = 1;
                        break;
                    }
                }
                if (!found) return 0;
            }
            return 1;
    }
    return 0;
}

/* Deep merge */
static json_value *deep_merge(json_value *a, json_value *b) {
    if (a->type == JSON_OBJECT && b->type == JSON_OBJECT) {
        json_value *result = json_new(JSON_OBJECT);
        for (int i = 0; i < a->obj_count; i++) {
            json_obj_put(result, a->obj_keys[i], a->obj_vals[i]);
        }
        for (int i = 0; i < b->obj_count; i++) {
            int found = -1;
            for (int j = 0; j < result->obj_count; j++) {
                if (strcmp(result->obj_keys[j], b->obj_keys[i]) == 0) { found = j; break; }
            }
            if (found >= 0) {
                json_free(result->obj_vals[found]);
                result->obj_vals[found] = deep_merge(a->obj_vals[found], b->obj_vals[i]);
            } else {
                json_obj_put(result, b->obj_keys[i], b->obj_vals[i]);
            }
        }
        return result;
    }
    if (a->type == JSON_ARRAY && b->type == JSON_ARRAY) {
        json_value *result = json_new(JSON_ARRAY);
        for (int i = 0; i < a->arr_count; i++) {
            json_arr_push(result, a->arr_items[i]);
        }
        for (int i = 0; i < b->arr_count; i++) {
            int dup = 0;
            for (int j = 0; j < result->arr_count; j++) {
                if (json_equal(result->arr_items[j], b->arr_items[i])) { dup = 1; break; }
            }
            if (!dup) {
                json_arr_push(result, b->arr_items[i]);
            }
        }
        return result;
    }
    return b;
}

/* Serializer with sorted keys and 2-space indent */
static void serialize_string(const char *s, FILE *f) {
    fputc('"', f);
    for (const char *p = s; *p; p++) {
        unsigned char c = (unsigned char)*p;
        if (c == '"') fputs("\\\"", f);
        else if (c == '\\') fputs("\\\\", f);
        else if (c == '\b') fputs("\\b", f);
        else if (c == '\f') fputs("\\f", f);
        else if (c == '\n') fputs("\\n", f);
        else if (c == '\r') fputs("\\r", f);
        else if (c == '\t') fputs("\\t", f);
        else if (c < 0x20) fprintf(f, "\\u%04x", c);
        else fputc(c, f);
    }
    fputc('"', f);
}

static void serialize_number(double d, FILE *f) {
    if (d == (long long)d && fabs(d) < 1e15) {
        fprintf(f, "%lld", (long long)d);
    } else {
        if (fabs(d) < 1e-4 && d != 0) {
            fprintf(f, "%.17g", d);
        } else {
            char tmp[64];
            int found = 0;
            for (int prec = 1; prec <= 17; prec++) {
                snprintf(tmp, sizeof(tmp), "%.*g", prec, d);
                if (strtod(tmp, NULL) == d) {
                    fputs(tmp, f);
                    found = 1;
                    break;
                }
            }
            if (!found) {
                fprintf(f, "%.17g", d);
            }
        }
    }
}

static void serialize_value(const json_value *v, int indent, FILE *f);

static void indent_str(int indent, FILE *f) {
    for (int i = 0; i < indent; i++) fputs("  ", f);
}

static void serialize_value(const json_value *v, int indent, FILE *f) {
    switch (v->type) {
        case JSON_NULL:
            fputs("null", f);
            break;
        case JSON_BOOL:
            fputs(v->bool_val ? "true" : "false", f);
            break;
        case JSON_NUMBER:
            serialize_number(v->num_val, f);
            break;
        case JSON_STRING:
            serialize_string(v->str_val, f);
            break;
        case JSON_ARRAY:
            if (v->arr_count == 0) {
                fputs("[]", f);
                return;
            }
            fputc('[', f);
            for (int i = 0; i < v->arr_count; i++) {
                fputc('\n', f);
                indent_str(indent + 1, f);
                serialize_value(v->arr_items[i], indent + 1, f);
                if (i < v->arr_count - 1) fputc(',', f);
            }
            fputc('\n', f);
            indent_str(indent, f);
            fputc(']', f);
            break;
        case JSON_OBJECT: {
            if (v->obj_count == 0) {
                fputs("{}", f);
                return;
            }
            int *idx = (int *)malloc(v->obj_count * sizeof(int));
            if (!idx) { fprintf(stderr, "OOM\n"); exit(1); }
            for (int i = 0; i < v->obj_count; i++) idx[i] = i;
            for (int i = 1; i < v->obj_count; i++) {
                int key = idx[i];
                int j = i - 1;
                while (j >= 0 && strcmp(v->obj_keys[idx[j]], v->obj_keys[key]) > 0) {
                    idx[j + 1] = idx[j];
                    j--;
                }
                idx[j + 1] = key;
            }
            fputc('{', f);
            for (int i = 0; i < v->obj_count; i++) {
                fputc('\n', f);
                indent_str(indent + 1, f);
                serialize_string(v->obj_keys[idx[i]], f);
                fputs(": ", f);
                serialize_value(v->obj_vals[idx[i]], indent + 1, f);
                if (i < v->obj_count - 1) fputc(',', f);
            }
            fputc('\n', f);
            indent_str(indent, f);
            fputc('}', f);
            free(idx);
            break;
        }
    }
}

static char *read_file(const char *path, int *out_len) {
    FILE *f = fopen(path, "rb");
    if (!f) {
        fprintf(stderr, "Cannot open %s\n", path);
        exit(1);
    }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = (char *)malloc(sz + 1);
    if (!buf) { fprintf(stderr, "OOM\n"); exit(1); }
    size_t rd = fread(buf, 1, sz, f);
    buf[rd] = '\0';
    *out_len = (int)rd;
    fclose(f);
    return buf;
}

int main(void) {
    const char *path_a = "<tmp>";
    const char *path_b = "<tmp>";

    int len_a, len_b;
    char *text_a = read_file(path_a, &len_a);
    char *text_b = read_file(path_b, &len_b);

    json_value *a = parse_json(text_a, len_a);
    json_value *b = parse_json(text_b, len_b);
    free(text_a);
    free(text_b);

    if (!a || !b) {
        fprintf(stderr, "Parse error\n");
        exit(1);
    }

    json_value *merged = deep_merge(a, b);
    json_free(a);
    json_free(b);

    serialize_value(merged, 0, stdout);
    fputc('\n', stdout);

    json_free(merged);
    return 0;
}
