    public static void main(String[] args) throws Exception {
        Path root = Paths.get("<tmp>");
        Map<String, List<FileInfo>> extMap = new TreeMap<>();
        Set<String> visitedDirs = new HashSet<>();

        walk(root, root, extMap, visitedDirs);

        System.out.println("=== File Tree Analysis ===");
        System.out.println();

        int totalFiles = 0;
        int totalLines = 0;
        int totalChars = 0;

        for (Map.Entry<String, List<FileInfo>> entry : extMap.entrySet()) {
