                    walk(entry, root, extMap, visitedDirs);
                } else if (Files.isRegularFile(entry)) {
                    String relPath = root.relativize(entry).toString().replace('\\', '/');
                    String fileName = entry.getFileName().toString();
                    String ext = getExtension(fileName);

                    byte[] bytes = Files.readAllBytes(entry);
                    int chars = bytes.length;
                    int lines = countLines(bytes);

                    extMap.computeIfAbsent(ext, k -> new ArrayList<>()).add(new FileInfo(relPath, lines, chars));
                }
            }
        }
    }

    static String getExtension(String filename) {
        int lastDot = filename.lastIndexOf('.');
        if (lastDot == -1) return "";
        if (lastDot == 0) return filename;
        return filename.substring(lastDot);
    }

    static int countLines(byte[] bytes) {
        if (bytes.length == 0) return 0;
        int count = 0;
        for (byte b : bytes) {
            if (b == '\n') count++;
        }
        if (bytes[bytes.length - 1] != '\n') count++;
