import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        String path = "<tmp>";

        StringBuilder sb = new StringBuilder();
        BufferedReader br = new BufferedReader(new FileReader(new File(path)));
        char[] buf = new char[4096];
        int n;
        while ((n = br.read(buf)) != -1) sb.append(buf, 0, n);
        br.close();
        String json = sb.toString();

        List<String> nodes = new ArrayList<>();
        List<String[]> edges = new ArrayList<>();

        // Parse nodes
        int nodesKey = json.indexOf("\"nodes\"");
        int bStart = json.indexOf('[', nodesKey);
        int bEnd = findMatchingBracket(json, bStart);
        String nodesStr = json.substring(bStart + 1, bEnd);
        for (String part : splitTopLevel(nodesStr, ',')) {
            String node = part.trim().replace("\"", "");
            if (!node.isEmpty()) nodes.add(node);
        }

        // Parse edges
        int edgesKey = json.indexOf("\"edges\"");
        int eStart = json.indexOf('[', edgesKey);
        int eEnd = findMatchingBracket(json, eStart);
        String edgesStr = json.substring(eStart + 1, eEnd);

        int pos = 0;
        while (pos < edgesStr.length()) {
            int objStart = edgesStr.indexOf('{', pos);
            if (objStart == -1) break;
            int objEnd = findMatchingBrace(edgesStr, objStart);
            String obj = edgesStr.substring(objStart, objEnd + 1);
            String from = extractString(obj, "from");
            String to = extractString(obj, "to");
            double weight = extractNumber(obj, "weight");
            edges.add(new String[]{from, to, String.valueOf(weight)});
            pos = objEnd + 1;
        }

        // Build adjacency list (undirected)
        Map<String, List<String[]>> adj = new HashMap<>();
        for (String n : nodes) adj.put(n, new ArrayList<>());
        for (String[] e : edges) {
            adj.get(e[0]).add(new String[]{e[1], e[2]});
            adj.get(e[1]).add(new String[]{e[0], e[2]});
        }

        // Dijkstra's algorithm
        Map<String, Double> dist = new HashMap<>();
        Set<String> visited = new HashSet<>();
        for (String n : nodes) dist.put(n, Double.MAX_VALUE);
        dist.put("A", 0.0);

        while (visited.size() < nodes.size()) {
            String u = null;
            double minDist = Double.MAX_VALUE;
            for (String n : nodes) {
                if (!visited.contains(n) && dist.get(n) < minDist) {
                    minDist = dist.get(n);
                    u = n;
                }
            }
            if (u == null || minDist == Double.MAX_VALUE) break;
            visited.add(u);

            for (String[] edge : adj.get(u)) {
                String v = edge[0];
                double w = Double.parseDouble(edge[1]);
                if (!visited.contains(v)) {
                    double nd = dist.get(u) + w;
                    if (nd < dist.get(v)) {
                        dist.put(v, nd);
                    }
                }
            }
        }

        // Output
        System.out.println("=== Shortest Paths from A ===");
        System.out.println();
        List<String> sorted = new ArrayList<>(nodes);
        Collections.sort(sorted);
        for (String n : sorted) {
            double d = dist.get(n);
            String distStr;
            if (d == Double.MAX_VALUE) {
                distStr = "unreachable";
            } else if (d == Math.floor(d) && !Double.isInfinite(d)) {
                distStr = String.valueOf((long) d);
            } else {
                distStr = String.valueOf(d);
            }
            System.out.println("A -> " + n + ": " + distStr);
        }
    }

    static int findMatchingBracket(String s, int openPos) {
        int depth = 0;
        for (int i = openPos; i < s.length(); i++) {
            if (s.charAt(i) == '[') depth++;
            else if (s.charAt(i) == ']') {
                depth--;
                if (depth == 0) return i;
            }
        }
        return s.length() - 1;
    }

    static int findMatchingBrace(String s, int openPos) {
        int depth = 0;
        for (int i = openPos; i < s.length(); i++) {
            if (s.charAt(i) == '{') depth++;
            else if (s.charAt(i) == '}') {
                depth--;
                if (depth == 0) return i;
            }
        }
        return s.length() - 1;
    }

    static List<String> splitTopLevel(String s, char delim) {
        List<String> parts = new ArrayList<>();
        int depth = 0;
        int start = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '[' || c == '{' || c == '"') {
                if (c == '"') {
                    // skip string
                    i++;
                    while (i < s.length() && s.charAt(i) != '"') {
                        if (s.charAt(i) == '\\') i++;
                        i++;
                    }
                } else depth++;
            } else if (c == ']' || c == '}') {
                depth--;
            } else if (c == delim && depth == 0) {
                parts.add(s.substring(start, i));
                start = i + 1;
            }
        }
        if (start < s.length()) parts.add(s.substring(start));
        return parts;
    }

    static String extractString(String obj, String key) {
        int idx = obj.indexOf("\"" + key + "\"");
        int colon = obj.indexOf(':', idx);
        int start = obj.indexOf('"', colon + 1);
        int end = obj.indexOf('"', start + 1);
        return obj.substring(start + 1, end);
    }

    static double extractNumber(String obj, String key) {
        int idx = obj.indexOf("\"" + key + "\"");
        int colon = obj.indexOf(':', idx);
        int start = colon + 1;
        while (start < obj.length() && (obj.charAt(start) == ' ' || obj.charAt(start) == '\t')) start++;
        int end = start;
        while (end < obj.length() && (Character.isDigit(obj.charAt(end)) || obj.charAt(end) == '.' || obj.charAt(end) == '-' || obj.charAt(end) == '+' || obj.charAt(end) == 'e' || obj.charAt(end) == 'E')) end++;
        return Double.parseDouble(obj.substring(start, end).trim());
    }
}

