typedef struct {
    char *name;
    int count;
} NameCount;

typedef struct {
    NameCount *items;
    int count;
    int capacity;
} NameCountArray;

void nca_init(NameCountArray *a) {
    a->items = NULL;
    a->count = 0;
    a->capacity = 0;
}

void nca_add(NameCountArray *a, const char *name) {
    for (int i = 0; i < a->count; i++) {
        if (strcmp(a->items[i].name, name) == 0) {
            a->items[i].count++;
            return;
        }
    }
    if (a->count >= a->capacity) {
        a->capacity = a->capacity ? a->capacity * 2 : 64;
        a->items = (NameCount *)realloc(a->items, a->capacity * sizeof(NameCount));
        if (!a->items) { fprintf(stderr, "OOM\n"); exit(1); }
    }
    a->items[a->count].name = strdup(name);
    a->items[a->count].count = 1;
    a->count++;
}

typedef struct {
    char **items;
    int count;
    int capacity;
} StrArray;

