    }
    if (a->count >= a->capacity) {
        a->capacity = a->capacity ? a->capacity * 2 : 64;
        a->items = (char **)realloc(a->items, a->capacity * sizeof(char *));
        if (!a->items) { fprintf(stderr, "OOM\n"); exit(1); }
    }
    a->items[a->count] = strdup(s);
    a->count++;
}

