static char *run_cmd(const char *cmd)
{
    FILE *fp = popen(cmd, "r");
    if (!fp)
        return NULL;

    size_t cap = 1024;
    size_t len = 0;
    char *buf = malloc(cap);
    if (!buf) {
        pclose(fp);
        return NULL;
    }

    size_t n;
    while ((n = fread(buf + len, 1, cap - len - 1, fp)) > 0) {
        len += n;
        if (len + 1 >= cap) {
            cap *= 2;
            char *tmp = realloc(buf, cap);
            if (!tmp) {
                free(buf);
                pclose(fp);
                return NULL;
            }
            buf = tmp;
        }
    }
    buf[len] = '\0';
    pclose(fp);

    while (len > 0 &&
           (buf[len - 1] == '\n' || buf[len - 1] == '\r' ||
            buf[len - 1] == ' '  || buf[len - 1] == '\t')) {
        buf[--len] = '\0';
    }

    return buf;
}

static char *dup_or_unknown(const char *s)
{
    if (!s)
        s = "unknown";
    size_t l = strlen(s);
    char *p = malloc(l + 1);
    if (p)
        memcpy(p, s, l + 1);
    else
        p = (char *)"unknown";
    return p;
}

int main(void)
{
    char *hostname = run_cmd("hostname");
    char *os       = run_cmd("uname -s");
    char *arch     = run_cmd("uname -m");
    char *username = run_cmd("whoami");

    char *h = dup_or_unknown(hostname);
    char *o = dup_or_unknown(os);
    char *a = dup_or_unknown(arch);
    char *u = dup_or_unknown(username);

    free(hostname);
    free(os);
    free(arch);
    free(username);

    printf("{\n");
    printf("  \"hostname\": \"%s\",\n", h);
    printf("  \"os\": \"%s\",\n", o);
    printf("  \"architecture\": \"%s\",\n", a);
    printf("  \"username\": \"%s\"\n", u);
    printf("}\n");

    free(h);
    free(o);
    free(a);
    free(u);

    return 0;
}

