            self.i += 1;
        }
    }

    fn peek(&self) -> Option<u8> {
        self.s.get(self.i).copied()
    }

    fn expect(&mut self, c: u8) {
        self.ws();
        assert!(
            self.i < self.s.len() && self.s[self.i] == c,
            "Expected '{}' at pos {}",
            c as char,
            self.i
        );
        self.i += 1;
    }

    fn parse_string(&mut self) -> String {
        self.expect(b'"');
        let mut out = String::new();
        loop {
            if self.i >= self.s.len() {
                panic!("Unterminated string");
            }
            let c = self.s[self.i];
            if c == b'"' {
                self.i += 1;
                break;
            } else if c == b'\\' {
                self.i += 1;
                let esc = self.s[self.i];
                self.i += 1;
                match esc {
                    b'"' => out.push('"'),
                    b'\\' => out.push('\\'),
                    b'/' => out.push('/'),
                    b'n' => out.push('\n'),
                    b't' => out.push('\t'),
                    b'r' => out.push('\r'),
                    b'b' => out.push('\u{0008}'),
                    b'f' => out.push('\u{000C}'),
                    b'u' => {
                        let mut code: u32 = 0;
                        for _ in 0..4 {
                            let h = self.s[self.i];
                            self.i += 1;
                            code = code * 16 + (h as char).to_digit(16).unwrap() as u32;
                        }
                        out.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                    }
                    _ => panic!("Bad escape"),
                }
            } else {
                out.push(c as char);
                self.i += 1;
            }
        }
        out
    }

    fn parse_number(&mut self) -> f64 {
        let start = self.i;
        if self.peek() == Some(b'-') {
            self.i += 1;
        }
        while self.i < self.s.len() && self.s[self.i].is_ascii_digit() {
            self.i += 1;
        }
        if self.i < self.s.len() && self.s[self.i] == b'.' {
            self.i += 1;
            while self.i < self.s.len() && self.s[self.i].is_ascii_digit() {
                self.i += 1;
            }
        }
        if self.i < self.s.len() && (self.s[self.i] == b'e' || self.s[self.i] == b'E') {
            self.i += 1;
            if self.i < self.s.len() && (self.s[self.i] == b'+' || self.s[self.i] == b'-') {
                self.i += 1;
            }
            while self.i < self.s.len() && self.s[self.i].is_ascii_digit() {
                self.i += 1;
            }
        }
        let text = std::str::from_utf8(&self.s[start..self.i]).unwrap();
        text.parse::<f64>().unwrap()
    }

    fn parse_value(&mut self) -> Json {
        self.ws();
        match self.peek() {
            Some(b'{') => self.parse_object(),
            Some(b'[') => self.parse_array(),
            Some(b'"') => Json::Str(self.parse_string()),
            Some(b'-') => Json::Num(self.parse_number()),
            Some(c) if c.is_ascii_digit() => Json::Num(self.parse_number()),
            Some(b't') => {
                self.i += 4;
                Json::Bool(true)
            }
            Some(b'f') => {
                self.i += 5;
                Json::Bool(false)
            }
            Some(b'n') => {
                self.i += 4;
                Json::Null
            }
            _ => panic!("Unexpected character at pos {}", self.i),
        }
    }

    fn parse_object(&mut self) -> Json {
        self.expect(b'{');
        let mut pairs = Vec::new();
        self.ws();
        if self.peek() == Some(b'}') {
            self.i += 1;
            return Json::Obj(pairs);
        }
        loop {
            self.ws();
            let key = self.parse_string();
            self.expect(b':');
            let val = self.parse_value();
            pairs.push((key, val));
            self.ws();
            match self.peek() {
                Some(b',') => {
                    self.i += 1;
                }
                Some(b'}') => {
                    self.i += 1;
                    break;
                }
                _ => panic!("Expected ',' or '}}' at pos {}", self.i),
            }
        }
        Json::Obj(pairs)
    }

    fn parse_array(&mut self) -> Json {
        self.expect(b'[');
        let mut items = Vec::new();
        self.ws();
        if self.peek() == Some(b']') {
            self.i += 1;
            return Json::Arr(items);
        }
        loop {
            let val = self.parse_value();
            items.push(val);
            self.ws();
            match self.peek() {
                Some(b',') => {
                    self.i += 1;
                }
                Some(b']') => {
                    self.i += 1;
                    break;
                }
                _ => panic!("Expected ',' or ']' at pos {}", self.i),
            }
        }
        Json::Arr(items)
    }
}

