import Foundation

let baseDir = "<tmp>"
let baseURL = URL(fileURLWithPath: baseDir)
let fileManager = FileManager.default

struct FileStats {
    let relativePath: String
    let lines: Int
    let chars: Int
}

var filesByExtension: [String: [FileStats]] = [:]
var visitedDirectories = Set<String>()

func walkDirectory(_ url: URL) {
    let path = url.path
    if visitedDirectories.contains(path) { return }
    visitedDirectories.insert(path)

    guard let contents = try? fileManager.contentsOfDirectory(at: url, includingPropertiesForKeys: nil, options: []) else { return }

    for fileURL in contents {
        let filePath = fileURL.path

        guard let attrs = try? fileManager.attributes(ofItemAt: filePath) else { continue }
        let type = attrs[.type] as? FileAttributeType

        if type == .typeSymbolicLink {
            continue
        }
        if type == .typeDirectory {
            walkDirectory(fileURL)
            continue
        }
        guard type == .typeRegular else { continue }

        let relativePath = String(filePath.dropFirst(baseDir.count + 1))

        guard let data = try? Data(contentsOf: fileURL) else { continue }

        let chars = data.count
        var lines = 0
        if !data.isEmpty {
            let newlineCount = data.reduce(0) { count, byte in
                count + (byte == 0x0A ? 1 : 0)
            }
            if data.last == 0x0A {
                lines = newlineCount
            } else {
                lines = newlineCount + 1
            }
        }

        let ext = fileURL.pathExtension
        let extKey = ext.isEmpty ? "" : "." + ext

        let stats = FileStats(relativePath: relativePath, lines: lines, chars: chars)
        filesByExtension[extKey, default: []].append(stats)
    }
}

walkDirectory(baseURL)

print("=== File Tree Analysis ===")
print("")

var totalFiles = 0
var totalLines = 0
var totalChars = 0

let sortedExtensions = filesByExtension.keys.sorted()

for ext in sortedExtensions {
    let files = filesByExtension[ext]!.sorted { $0.relativePath < $1.relativePath }
    let fileCount = files.count
    let extLines = files.reduce(0) { $0 + $1.lines }
    let extChars = files.reduce(0) { $0 + $1.chars }

    print("Extension: \(ext)")
    print("  Files: \(fileCount)")
    print("  Total Lines: \(extLines)")
    print("  Total Characters: \(extChars)")
    for file in files {
        print("    \(file.relativePath): \(file.lines) lines, \(file.chars) chars")
    }

    totalFiles += fileCount
    totalLines += extLines
    totalChars += extChars
}

print("")
