fn main() {
    let root = Path::new("<tmp>");

    let mut files: Vec<(String, String, usize, usize)> = Vec::new();

    walk(root, root, &mut files);

    let mut groups: BTreeMap<String, Vec<(String, usize, usize)>> = BTreeMap::new();

    for (ext, rel, lines, chars) in &files {
        groups.entry(ext.clone()).or_default().push((rel.clone(), *lines, *chars));
    }

    for v in groups.values_mut() {
        v.sort_by(|a, b| a.0.cmp(&b.0));
    }

    println!("=== File Tree Analysis ===");
    println!();

    for (ext, file_list) in &groups {
        println!("Extension: {}", ext);
        println!("  Files: {}", file_list.len());
        let total_lines: usize = file_list.iter().map(|f| f.1).sum();
        let total_chars: usize = file_list.iter().map(|f| f.2).sum();
        println!("  Total Lines: {}", total_lines);
        println!("  Total Characters: {}", total_chars);
        for (rel, lines, chars) in file_list {
            println!("    {}: {} lines, {} chars", rel, lines, chars);
        }
    }

    println!();

    let total_files = files.len();
    let total_lines: usize = files.iter().map(|f| f.2).sum();
    let total_chars: usize = files.iter().map(|f| f.3).sum();
    println!("Total: {} files, {} lines, {} characters", total_files, total_lines, total_chars);
}

fn walk(dir: &Path, root: &Path, files: &mut Vec<(String, String, usize, usize)>) {
    let entries = match fs::read_dir(dir) {
        Ok(e) => e,
        Err(_) => return,
    };

    for entry in entries {
        let entry = match entry {
            Ok(e) => e,
            Err(_) => continue,
        };

        let path = entry.path();

        if path.is_symlink() {
            continue;
        }

        if path.is_dir() {
            walk(&path, root, files);
        } else if path.is_file() {
            let rel = path.strip_prefix(root).unwrap_or(&path);
            let rel_str = rel.to_string_lossy().replace('\\', "/");

            let ext = path
                .extension()
                .map(|e| format!(".{}", e))
                .unwrap_or_default();

            let (lines, chars) = read_file_stats(&path);

            files.push((ext, rel_str, lines, chars));
        }
    }
}

fn read_file_stats(path: &Path) -> (usize, usize) {
    let metadata = match fs::metadata(path) {
        Ok(m) => m,
        Err(_) => return (0, 0),
    };

    let chars = metadata.len() as usize;

    let mut content = Vec::new();
    let mut file = match fs::File::open(path) {
        Ok(f) => f,
        Err(_) => return (0, chars),
    };

    if file.read_to_end(&mut content).is_err() {
        return (0, chars);
    }

    if content.is_empty() {
        return (0, 0);
    }

    let newline_count = content.iter().filter(|&&b| b == b'\n').count();
    let lines = if content.last() == Some(&b'\n') {
        newline_count
    } else {
        newline_count + 1
    };

    (lines, chars)
}

