    if (groups_count > 0) {
        ExtGroup **gptrs = malloc((size_t)groups_count * sizeof(ExtGroup *));
        if (!gptrs) { fprintf(stderr, "OOM\n"); exit(1); }
        for (int i = 0; i < groups_count; i++) gptrs[i] = &groups[i];
        qsort(gptrs, (size_t)groups_count, sizeof(ExtGroup *), cmp_groups);
        for (int i = 0; i < groups_count; i++) {
            groups[i] = *gptrs[i];
        }
        free(gptrs);
    }

    for (int i = 0; i < groups_count; i++) {
        if (groups[i].count > 1) {
            qsort(groups[i].files, (size_t)groups[i].count, sizeof(FileInfo *), cmp_file_ptrs);
        }
    }

    printf("=== File Tree Analysis ===\n");
    printf("\n");

    long total_files = 0;
    long total_lines = 0;
    long total_chars = 0;

    for (int i = 0; i < groups_count; i++) {
        ExtGroup *g = &groups[i];
        printf("Extension: %s\n", g->ext);
        printf("  Files: %d\n", g->count);
        printf("  Total Lines: %ld\n", g->total_lines);
        printf("  Total Characters: %ld\n", g->total_chars);
        for (int j = 0; j < g->count; j++) {
            printf("    %s: %ld lines, %ld chars\n", g->files[j]->relpath, g->files[j]->lines, g->files[j]->chars);
        }
        total_files += (long)g->count;
        total_lines += g->total_lines;
        total_chars += g->total_chars;
    }

    printf("\n");
    printf("Total: %ld files, %ld lines, %ld characters\n", total_files, total_lines, total_chars);

    return 0;
}
